import re

def parse_duration(s):
    total = 0
    for num_str, unit in re.findall(r'(\d+)([hms])', s):
        num = int(num_str)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total
